def probability(N, M, P, K):
    if N*M < 2:
        return 1
    if P > K:
        return 0
    if P == K:
        return 1
    chef_wins = 0
    for _ in range(1000000):
        board = [[0 for _ in range(M)] for _ in range(N)]
        x, y = 0, 0
        board[x][y] = 1
        for _ in range(K):
            rule = random.randint(0, 1)
            if rule == 0:
                dx = [1, -1, 0, 0]
                dy = [0, 0, 1, -1]
            else:
                dx = [1, 1, -1, -1]
                dy = [1, -1, 1, -1]
            for i in range(4):
                nx, ny = x + dx[i], y + dy[i]
                if 0 <= nx < N and 0 <= ny < M and board[nx][ny] == 0:
                    x, y = nx, ny
                    board[x][y] = 1
                    break
        if sum([1 for row in board for cell in row if cell == 1]) >= P:
            chef_wins += 1
    return chef_wins / 1000000

