            edges.append((u, v))
        edges.sort()
        count = 0
        triple = []
        for i in range(N-1):
            u, v = edges[i]
            if i < N-2 and edges[i+1][0] == u:
                continue
            for j in range(i+1, N-1):
                w, x = edges[j]
                if w == u or w == v or x == u or x == v:
                    continue
                for k in range(j+1, N-1):
                    y, z = edges[k]
                    if y == u or y == v or z == u or z == v:
                        continue
                    triple.append((u, v, w, x, y, z))
                    count += 1
                    if count == (N-1)//3:
                        break
                if count == (N-1)//3:
                    break
            if count == (N-1)//3:
                break
        if count == (N-1)//3:
            print("YES")
            for t in triple:
                print(*t)
        else:
            print("NO")

