def count_subsequences(A, K, M):
    n = len(A)
    dp = [[0]*(M+1) for _ in range(n+1)]
    for i in range(n+1):
        dp[i][0] = 1
    for i in range(1, n+1):
        for j in range(1, M+1):
            if A[i-1] % M == j % M:
                dp[i][j] = (dp[i-1][j-1] + dp[i-1][j]) % MOD
            else:
                dp[i][j] = dp[i-1][j]
    return dp[n][M]

