def can_eat_k_chocolates(k, boxes):
    def dfs(index, current_sum):
        if current_sum == k:
            return True
        if current_sum > k or index == len(boxes):
            return False
        return dfs(index + 1, current_sum + boxes[index]) or dfs(index + 1, current_sum)

    return 1 if dfs(0, 0) else 0

