    for i in range(n):
        max_len = 0
        max_start = -1
        current_len = 0
        current_start = -1
        for j in range(n):
            if result[j] == 0:
                if current_len == 0:
                    current_start = j
                current_len += 1
            else:
                if current_len > max_len:
                    max_len = current_len
                    max_start = current_start
                current_len = 0
        if current_len > max_len:
            max_len = current_len
            max_start = current_start
        mid = (max_start + max_len - 1) // 2
        if (max_len % 2 == 1):
            result[mid] = i + 1
        else:
            result[mid] = i + 1
    return result

