import heapq

def max_money(n, A, k):
    if k == 0:
        return 0
    if n == 1:
        return A[0]
    if k >= n - 1:
        return sum(A)

    # Priority queue to store the negative values of money in rooms
    pq = []
    for i in range(1, n-1):
        heapq.heappush(pq, -A[i])

    for _ in range(k):
        if pq:
            max_money = -heapq.heappop(pq)
            if max_money > 0:
                max_money -= 1
                heapq.heappush(pq, -max_money)

    return sum(A) - sum([-x for x in pq])

