def max_score(s):
    x, y = 0, 0
    for char in s:
        if char == 'U':
            y += 1
        elif char == 'D':
            y -= 1
        elif char == 'L':
            x -= 1
        elif char == 'R':
            x += 1
    stack = []
    for char in s:
        if char == 'U':
            y += 1
        elif char == 'D':
            y -= 1
        elif char == 'L':
            x -= 1
        elif char == 'R':
            x += 1
        if x == 0 and y == 0:
            stack.append(char)
    return len(s) - len(stack)

