def max_cool_down_time(N, D, C):
    C.sort()
    low, high = 0, C[-1] - C[0]
    while low < high:
        mid = (low + high + 1) / 2
        if all(C[i] + D > C[i - 1] + mid for i in range(1, N)):
            low = mid
        else:
            high = mid - 1
    return low

