    if n == 1 or n == 2:
        return max(a, b)
    xoronacci = [a, b]
    xnoronacci = [a, b]
    for i in range(2, n):
        xoronacci.append(xoronacci[-1] ^ xoronacci[-2])
        xnoronacci.append(xnoronacci[-1] and xnoronacci[-2])
    return max(xoronacci[-1], xnoronacci[-1])

