def count_numbers(N, W):
    if W == 0:
        return 1
    if W > 9 * (N - 1):
        return 0
    dp = [[0] * (W + 1) for _ in range(N + 1)]
    dp[1][0] = 1
    for i in range(2, N + 1):
        for j in range(W + 1):
            dp[i][j] = sum(dp[i - 1][max(0, j - 9):j]) % MOD
    return dp[N][W]

