def find_string(s, k):
    used = [False] * 26
    for char in s:
        used[ord(char) - ord('a')] = True

    count = sum(1 for u in used if u)
    if count <= k:
        return "".join(chr(i + ord('a')) for i in range(26) if not used[i])

    result = [""] * 26
    index = 0
    for i in range(26):
        if used[i]:
            result[index] = chr(i + ord('a'))
            index += 1
        else:
            if k > 0:
                result[index] = chr(i + ord('a'))
                k -= 1
                index += 1

    if k > 0:
        return "NOPE"

    return "".join(result[:len(s)])

