def get_first_non_zero_digit(number):
    while number >= 10:
        number /= 10
    return int(number)

def solve(N, A, B, C):
    lst = deque([N])
    while len(lst) < 1000:
        N = lst[-1]
        if N % A == 0:
            lst.append(int(N / A))
        else:
            lst.append(get_first_non_zero_digit(N / A))
        if N % B == 0:
            lst.append(int(N / B))
        else:
            lst.append(get_first_non_zero_digit(N / B))
        if N % C == 0:
            lst.append(int(N / C))
        else:
            lst.append(get_first_non_zero_digit(N / C))
    return lst

