import sys
from collections import defaultdict, deque

def find_node(N, edges, a, da, b, db):
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    def bfs(start, target_distance):
        visited = [False] * (N + 1)
        distance = [0] * (N + 1)
        queue = deque([start])
        visited[start] = True

        while queue:
            node = queue.popleft()
            if distance[node] == target_distance:
                return node
            for neighbor in tree[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    distance[neighbor] = distance[node] + 1
                    queue.append(neighbor)

        return -1

    node_a = bfs(a, da)
    if node_a == -1:
        return -1

    node_b = bfs(b, db)
    if node_b == -1:
        return -1

    def find_lca(node1, node2):
        path1 = set()
        while node1 != -1:
            path1.add(node1)
            node1 = find_parent[node1]

        while node2 not in path1:
            node2 = find_parent[node2]

        return node2

    def find_parent(node):
        queue = deque([node])
        parent = [-1] * (N + 1)
        visited = [False] * (N + 1)
        visited[node] = True

        while queue:
            current = queue.popleft()
            for neighbor in tree[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    parent[neighbor] = current
                    queue.append(neighbor)

        return parent

    find_parent = find_parent(a)
    lca = find_lca(node_a, node_b)

    def is_common_ancestor(x, a, b):
        return lca in [a, b] or (x != lca and x in [a, b])

    def find_common_node(x, a, b):
        if is_common_ancestor(x, a, b):
            return x
        if x == a:
            return b
        if x == b:
            return a
        return -1

    return find_common_node(lca, node_a, node_b)

