def solve(p, q, r):
    MOD = 998244353
    if q % 2 != 0:
        return 0
    q //= 2
    if p < q or p + q < r:
        return 0
    if p + q == r:
        return 1
    dp = [0] * (p + q + 1)
    dp[0] = 1
    for i in range(1, p + q + 1):
        dp[i] = (dp[i - 1] * (i + r - 1)) % MOD
    return dp[p + q] * pow(p + q + 1, MOD - 2, MOD) % MOD

