def count_regions(n, napkin):
    from collections import deque

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[False] * 8 for _ in range(8)]
    regions = 0

    def bfs(x, y):
        queue = deque([(x, y)])
        visited[x][y] = True
        while queue:
            cx, cy = queue.popleft()
            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < 8 and 0 <= ny < 8 and not visited[nx][ny] and napkin[nx][ny] == '1':
                    visited[nx][ny] = True
                    queue.append((nx, ny))

    for i in range(8):
        for j in range(8):
            if napkin[i][j] == '1' and not visited[i][j]:
                regions += 1
                bfs(i, j)

    return regions

