def next_repetition_free_number(n):
    digits = list(map(int, str(n)))
    length = len(digits)

    for i in range(length - 1, -1, -1):
        if i > 0 and digits[i] > digits[i - 1]:
            suffix = digits[i:]
            smallest_larger = min(filter(lambda x: x > suffix[0], suffix))
            suffix.remove(smallest_larger)
            suffix.sort()
            digits[i:] = [smallest_larger] + suffix
            return int(''.join(map(str, digits)))

    if n == 999999999:
        return 888888888

    return 0

