def min_proxy_attendance(D, S):
    if D == 1:
        return 1 if S == 'A' else 0
    if D == 2:
        return 1 if S == 'AA' else 0
    if D == 3:
        return 1 if S == 'AAA' else 0
    if D == 4:
        return 1 if S == 'AAAA' else 0

    proxy_needed = [0] * D
    for i in range(2, D-2):
        if S[i] == 'A':
            if S[i-2] == 'P' and S[i-1] == 'P' and S[i+1] == 'P' and S[i+2] == 'P':
                proxy_needed[i] = 0
            else:
                proxy_needed[i] = 1
    if S[1] == 'A' and S[2] == 'P' and S[3] == 'P':
        proxy_needed[1] = 0
    else:
        proxy_needed[1] = 1
    if S[D-2] == 'A' and S[D-3] == 'P' and S[D-4] == 'P':
        proxy_needed[D-2] = 0
    else:
        proxy_needed[D-2] = 1

    total_attendance = sum(1 for char in S if char == 'P') + sum(proxy_needed)
    if total_attendance * 100 >= 75 * D:
        return sum(proxy_needed)
    else:
        return -1

