def min_steps_to_reach(X):
    if X == 1:
        return "2"
    if X == 2:
        return "21"
    if X % 2 == 0:
        return "0"

    n = 1
    steps = []
    while n * (n + 1) // 2 < X:
        n += 1

    total_steps = n * (n + 1) // 2
    remaining = total_steps - X

    if remaining % 2 != 0:
        return "0"

    half_remaining = remaining // 2
    steps.append(2)
    for _ in range(half_remaining):
        steps.append(1)
    for _ in range(n - half_remaining - 1):
        steps.append(2)

    return ''.join(map(str, steps))

