    if K % 2 == 1:
        return -1
    if K // 2 < N - 1:
        return -1
    if K // 2 == N - 1:
        return list(range(1, N + 1))
    target = K // 2 - (N - 1)
    result = [N, N - 1]
    current = N - 2
    while current > 0:
        if target >= current:
            result.append(current)
            target -= current
        else:
            result.append(target)
            break
        current -= 1
    return result

