def max_valid_subsequence_sum(n: int, k: int, a: List[int]) -> int:
    even_sum = [0] * (n + 1)
    odd_sum = [0] * (n + 1)

    for i in range(n):
        even_sum[i + 1] = even_sum[i]
        odd_sum[i + 1] = odd_sum[i]

        if a[i] % 2 == 0:
            even_sum[i + 1] = max(even_sum[i + 1], odd_sum[i] + a[i])
        else:
            odd_sum[i + 1] = max(odd_sum[i + 1], even_sum[i] + a[i])

    return max(even_sum[-1], odd_sum[-1])

