    N = len(A)
    max_lis = 0
    min_m = float('inf')

    for M in range(1, N+1):
        B = A * M
        lis = [1] * N
        for i in range(1, N*M):
            if B[i] > B[i-1]:
                lis[i % N] = lis[(i-1) % N] + 1
        max_lis = max(max_lis, max(lis))

    for M in range(1, N+1):
        B = A * M
        lis = [1] * N
        for i in range(1, N*M):
            if B[i] > B[i-1]:
                lis[i % N] = lis[(i-1) % N] + 1
        if max(lis) == max_lis:
            min_m = min(min_m, M)
            break

    return min_m

