import sys

def least_prime_divisor(n: int) -> int:
    if n % 2 == 0:
        return 2
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return i
    return n if n > 1 else 1

def update(arr: List[int], L: int, R: int) -> None:
    for i in range(L - 1, R):
        arr[i] //= least_prime_divisor(arr[i])

def get_max_divisor(arr: List[int], L: int, R: int) -> int:
    result = 1
    for i in range(L - 1, R):
        result = max(result, least_prime_divisor(arr[i]))
    return result

