def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def lcm(x, y):
    return x * y // gcd(x, y)

def solve(n):
    factors = prime_factors(n)
    divisors = sorted(set(factors))
    initial_order = [1] + divisors + [1]
    moves = 0
    for i in range(1, len(initial_order) - 1):
        if gcd(initial_order[i - 1], initial_order[i + 1]) == 1:
            moves += 1
            initial_order.insert(i, lcm(initial_order[i - 1], initial_order[i + 1]))
    return initial_order[1:-1], moves

