def count_non_intersecting_segments(n, a):
    last_seen = {}
    count = 0
    for i in range(n):
        if a[i] not in last_seen:
            last_seen[a[i]] = (i, i)
        else:
            start, end = last_seen[a[i]]
            count += (start * (n - end - 1))
            last_seen[a[i]] = (start, i)
    return count

