def game_winner(N, K, A, S):
    chef_score = 0
    garry_score = 0
    turn = 0

    while A:
        if turn % 2 == 0:  # Chef's turn
            for x in S:
                if x <= len(A):
                    chef_score += sum(2 ** p for p in A[:x])
                    A = A[x:]
                    break
        else:  # Garry's turn
            for x in S:
                if x <= len(A):
                    garry_score += sum(2 ** p for p in A[:x])
                    A = A[x:]
                    break
        turn += 1

    if chef_score > garry_score:
        return "Chef"
    elif garry_score > chef_score:
        return "Garry"
    else:
        return "Draw"

