from collections import deque

def min_tree_height(n, a):
    height = 0
    level = {1: 0}
    q = deque([1])
    while q:
        current = q.popleft()
        for child in range(current * 2, current * 2 + 2):
            if child <= n and child == a[a.index(current) + 1]:
                level[child] = level[current] + 1
                q.append(child)
        height = max(height, level[current])
    return height

