MOD = 10**9 + 7

def factorial(n):
    res = 1
    for i in range(1, n + 1):
        res = (res * i) % MOD
    return res

def inv_mod(n):
    return pow(n, MOD - 2, MOD)

def count_permutations(N):
    if N < 2:
        return 0
    fact = factorial(N)
    inv_fact = inv_mod(fact)
    res = (fact * inv_fact) % MOD
    for i in range(2, N):
        res -= (fact * inv_fact) % MOD
        fact = (fact * i * (N - i)) % MOD
        inv_fact = (inv_fact * (N - i)) % MOD
        res = (res + MOD) % MOD
    return res

