def count_special_numbers(N):
    special_count = 0
    partial_special_count = 0

    for i in range(1, N):
        product = 1
        temp = i
        while temp > 0:
            digit = temp % 10
            if digit == 1:
                partial_special_count += 1
            elif product > N // digit:
                break
            else:
                product *= digit
            temp //= 10
        if product == N:
            special_count += 1

    partial_special_count += N // 10 if N >= 10 else 0

    return special_count, partial_special_count

