def max_antichain(n, edges):
    adj_list = {i: [] for i in range(1, n+1)}
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    visited = [False] * (n+1)
    max_antichain_size = 0

    def dfs(node):
        nonlocal max_antichain_size
        visited[node] = True
        for neighbor in adj_list[node]:
            if not visited[neighbor]:
                dfs(neighbor)
        if not any(visited[neigh] for neigh in adj_list[node]):
            max_antichain_size += 1
            visited[node] = True

    for i in range(1, n+1):
        if not visited[i]:
            dfs(i)

    return max_antichain_size

