from collections import defaultdict

def solve_test_case():
    n, m = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(m)]

    graph = defaultdict(list)
    for t, u, v in edges:
        if t == 0:
            graph[u].append(v)
            graph[v].append(u)

    visited = set()
    order = []

    def dfs(node):
        if node in visited:
            return False
        visited.add(node)
        for neighbor in graph[node]:
            if not dfs(neighbor):
                return False
        order.append(node)
        return True

    for node in range(1, n + 1):
        if node not in visited:
            if not dfs(node):
                return False, None

    order.reverse()

    for u, v in edges:
        if u == v:
            continue
        if u not in order or v not in order:
            return False, None
        if u > v and order.index(u) > order.index(v):
            return False, None

    return True, edges

