    H.sort(reverse=True)
    count = 0
    for i in range(N):
        if M == 0 or S == 0:
            break
        if H[i] <= S:
            count += 1
            M -= 1
            if i >= 1 and H[i-1] <= S:
                count += 1
                M -= 1
                if i >= 2 and H[i-2] <= S:
                    count += 1
                    M -= 1
        S -= H[i]
    return count

