def C(n, k):
    if k > n:
        return 0
    if k > n - k:
        k = n - k
    num = den = 1
    for i in range(k):
        num = (num * (n - i)) % MOD
        den = (den * (i + 1)) % MOD
    return (num * pow(den, MOD - 2, MOD)) % MOD

