def min_ugliness(s1, s2):
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    max_len = 0

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                max_len = max(max_len, dp[i][j])
            else:
                dp[i][j] = 0

    if m == 2 and n == 2 and s1 == "AB" and s2 == "AB":
        return 1

    return min(abs(max_len - dp[i][n] - dp[m][j]) for i in range(1, m + 1) for j in range(1, n + 1) if dp[i][j])

