def move_ants(grid, R, C):
    ant_positions = defaultdict(list)
    for i in range(R):
        for j in range(C):
            if grid[i][j] == '#':
                ant_positions[grid[i][j]].append((i, j))
            elif grid[i][j] != '-':
                dr, dc = get_direction(grid[i][j])
                ni, nj = i + dr, j + dc
                if 0 <= ni < R and 0 <= nj < C and grid[ni][nj] == '-':
                    ant_positions[grid[i][j]].append((ni, nj))
    pairs = 0
    for position in ant_positions.values():
        for i in range(len(position)):
            for j in range(i + 1, len(position)):
                if position[i] == position[j]:
                    pairs += 1
    return pairs

