def game_winner(N, K, stack, S):
    score = [0] * (N + 1)
    for i in range(1, N + 1):
        score[i] = score[i - 1] + 2 ** stack[i - 1]

    dp = [[0] * (K + 1) for _ in range(N + 1)]
    for i in range(1, N + 1):
        for j in range(1, K + 1):
            if i >= j:
                dp[i][j] = max(score[i] - score[i - j], dp[i - j][j])
                for x in S:
                    if i >= x and j + x <= K:
                        dp[i][j] = max(dp[i][j], score[i - x] - score[max(0, i - x - j)])
    return "Chef" if dp[N][K] > 0 else "Garry" if dp[N][K] < 0 else "Draw"

