def min_swaps_to_sort(N, D, P):
    position = {val: idx for idx, val in enumerate(P)}
    sorted_P = sorted(P)
    count = 0
    for i in range(N):
        if P[i] != sorted_P[i]:
            target_val = sorted_P[i]
            target_pos = position[target_val]
            if abs(i - target_pos) == D:
                P[i], P[target_pos] = P[target_pos], P[i]
                position[P[i]], position[P[target_pos]] = target_pos, i
                count += 1
            else:
                return -1
    return count

