def max_occurrence(N, heights):
    heights = [0] + heights + [0]
    max_count = 0
    count_dict = {}

    for i in range(1, N+1):
        for j in range(heights[i-1]+1, heights[i]):
            if j not in count_dict:
                count_dict[j] = 0
            count_dict[j] += 1
            max_count = max(max_count, count_dict[j])

        if i == N and heights[i] == heights[i-1]:
            max_count -= 1

    return max_count

N = int(input())
heights = list(map(int, input().split()))
print(max_occurrence(N, heights))

MOD = 10**9 + 7

def last_node(S):
    path = []
    for char in S:
        if char == 'l':
            path.append(2)
        else:
            path.append(3)
    return sum(path) % MOD

T = int(input())
for _ in range(T):
    S = input()
    print(last_node(S))
